-- GENERADO POR scripts/build-seed.mjs — no editar a mano.
-- Editar supabase/seed/catalog.mjs y ejecutar `npm run seed:build`.

begin;

-- Juegos ------------------------------------------------------------------
on conflict (slug) do update
  set name = excluded.name, release_year = excluded.release_year;

-- Sliders -----------------------------------------------------------------
on conflict (game_id, slug, applies_to) do update
  set category      = excluded.category,
      name          = excluded.name,
      min_value     = excluded.min_value,
      max_value     = excluded.max_value,
      default_value = excluded.default_value,
      sort_order    = excluded.sort_order;

-- Limpieza de sliders que ya no están en el catálogo ---------------------
delete from public.slider_definitions
where game_id = (select id from public.games where slug = 'fc27')
  and slug not in ('sprint_speed', 'acceleration', 'shot_error', 'shot_speed', 'header_shot_error', 'pass_error', 'pass_speed', 'header_pass_error', 'power_bar', 'first_touch_error', 'interception_error', 'deflection_error', 'tackle_assistance', 'goalkeeper_ability', 'marking', 'run_frequency', 'line_height', 'line_length', 'line_width', 'defensive_positioning', 'injury_frequency', 'injury_severity', 'cpu_tackle_aggression', 'cpu_buildup_speed', 'cpu_shot_frequency', 'cpu_first_touch_pass_frequency', 'cpu_cross_frequency', 'cpu_dribble_frequency', 'cpu_flair_frequency');

delete from public.slider_definitions
where game_id = (select id from public.games where slug = 'fc26')
  and slug not in ('sprint_speed', 'acceleration', 'shot_error', 'shot_speed', 'header_shot_error', 'pass_error', 'pass_speed', 'header_pass_error', 'power_bar', 'first_touch_error', 'interception_error', 'deflection_error', 'tackle_assistance', 'goalkeeper_ability', 'marking', 'run_frequency', 'line_height', 'line_length', 'line_width', 'defensive_positioning', 'injury_frequency', 'injury_severity', 'cpu_tackle_aggression', 'cpu_buildup_speed', 'cpu_shot_frequency', 'cpu_first_touch_pass_frequency', 'cpu_cross_frequency', 'cpu_dribble_frequency', 'cpu_flair_frequency');

commit;
